//--------------------------------------------------------------------------------------
//                                    
//   HTTP GET function                                 
//	                                   
// __________________________________________________________________________________


						
CASE GET_Step OF

	0: 	//Init
		SktGetTCPStatus_Inst(Execute	:=FALSE);
		SktTCPConnect_Inst(Execute	:=FALSE);
		SktClose_Inst(Execute				:=FALSE);
		Busy											:=FALSE;
		GET_Step									:=INT#1;		
		
	1: //  Waiting for Execute -----------------------------------------------		
			IF Execute AND NOT old_Execute THEN
				GET_Step:=INT#2;
			END_IF;
			
			IF  Done AND NOT Execute THEN 
				Done:=FALSE;
				ErrorID:=0;
				HttpStatCode:=0;
				Status:='';
			END_IF;
			
			IF Error AND NOT Execute THEN
				Error:=FALSE;
				ErrorID:=0;
				HttpStatCode:=0;
				Status:='';
			END_IF;
			old_Execute:=Execute;

	2:	//  Connect socket -------------------------------------------------------------
			Status:='Connecting to the HTTP Server'; 
			Error												:=FALSE;
			ErrorID											:=WORD#0;
			Busy												:=TRUE;
			IF Use_Proxy THEN
				SktTCPConnect_Inst(Execute	:=TRUE,
										SrcTcpPort		:=LocalPort,
										DstAdr				:=Proxy_Address,
										DstTcpPort		:=Proxy_Port,
							 			Socket 				=>HTTP_Socket);		
			ELSE
				SktTCPConnect_Inst(Execute	:=TRUE,
										SrcTcpPort		:=LocalPort,
										DstAdr				:=Server_IPaddr,
										DstTcpPort		:=HTTP_Port ,
							 			Socket 				=>HTTP_Socket);
			END_IF;
			
			IF (SktTCPConnect_Inst.Done)		 THEN 
				SktTCPConnect_Inst(Execute:=FALSE);
				GET_Step								:=INT#3;
			ELSIF (SktTCPConnect_Inst.Error) THEN
				ErrorID										:=SktTCPConnect_Inst.ErrorID;
				Status										:='Connection failed';
				GET_Step								:=INT#200;
			END_IF;	
			   

	3: // check socket status connexion ---------------------------------------------
			Status:='Checking Socket status';
			IF (HTTP_Socket.Handle >UDINT#0) THEN
				SktGetTCPStatus_Inst(Execute			:=TRUE,Socket:=HTTP_Socket);
				IF (SktGetTCPStatus_Inst.Done)  OR (SktGetTCPStatus_Inst.Error) THEN
					IF (SktGetTCPStatus_Inst.TcpStatus= _ESTABLISHED) THEN
							GET_Step					:=INT#4;																	// --> Send GET
					ELSE
							ErrorID						:=SktGetTCPStatus_Inst.ErrorID;
							Status						:='Could not connect to the server';
							GET_Step					:=INT#200;																	// --> Close Socket
					END_IF;
				END_IF;
			END_IF;
	
	4:	// Compose and GET HTTP message  -----------------------------------------------------
			Status:='Sending GET command';
			Request:=CONCAT('GET ',Get_Url,' HTTP/1.1','$R$L');
			Request:=CONCAT(Request,'Host: ', Server_IPaddr);
			IF HTTP_Port <> 80 THEN	Request:=CONCAT(Request,':',UINT_TO_STRING(HTTP_Port)); END_IF;
			Request:=CONCAT(Request,'$R$L');
			// adds optional headers
			IF N_Headers > 0 THEN
				FOR i:=0 TO N_Headers-1 DO
					Request:=CONCAT(Request,Add_Headers[i],'$R$L');
				END_FOR;
			END_IF;
			// adds a blank line at the end
			Request:=CONCAT(Request,'$R$L');
			// send message
			SendReceive(HTTP_Socket, Request,Timeout,Response,ErrID,InstDone);									// --> send request
										
			IF SendReceive.Done THEN
					IF ErrID >0 THEN 
						ErrorID							:=ErrID;
						GET_Step						:=INT#200;																// --> Close Socket
					ELSE
						pos:=FIND(Response,'HTTP');
						IF pos > 0 THEN														// Check for correct user connexion
							StatCode:=STRING_TO_UINT(MID(Response,3,10));
							GET_Step					:=INT#5;
						ELSE
							//Error							:=TRUE;
							Status						:=CONCAT('Wrong response',Response);
							GET_Step					:=INT#200;																// --> Close Socket
						END_IF;
					END_IF;
			END_IF;
				
				
	5: //   Decode reply -------------------------------------------------
				Status:='Decoding reply';
				HttpStatCode:=StatCode;
				IF Output_Raw_Data THEN
					Message_Body:=Response;
				ELSE
					IF StatCode = 200 THEN
						RespLen:=LEN(Response);
						pos:=FIND(Response,'Content-Length:');
						IF pos > 0 THEN
							Response:=RIGHT(Response, RespLen-pos-15);
							RespLen:=RespLen-pos-15;
							pos:=FIND(Response,'$R$L');
							BodyLen:=STRING_TO_UINT(LEFT(Response,pos-1));
							IF BodyLen >0 THEN
								pos:=FIND(Response,'$R$L$R$L');
								Message_Body:=RIGHT(Response,RespLen-pos-3);
							ELSE
								Message_Body:='';
							END_IF;
						ELSE
							pos:=FIND(Response,'$R$L$R$L');
							Response:=RIGHT(Response, RespLen-pos-3);
							RespLen:=RespLen-pos-3;
							pos:=FIND(Response,'$R$L$R$L');
							IF pos > 0 THEN 
								Message_Body:=Response;
							ELSE
								Message_Body:='';
							END_IF;
						END_IF;
					END_IF;
				END_IF;
				GET_Step:=100;
				
	100: // Normal end, Close TCP port   -----------------------------------------------------
		SktClose_Inst(Execute	:=TRUE, Socket	:=HTTP_Socket);
		
		IF SktClose_Inst.Done OR SktClose_Inst.Error THEN			
			IF SktClose_Inst.Error THEN ErrorID	:=SktClose_Inst.ErrorID; END_IF;
			Done:=TRUE;
			Busy	:=FALSE;
			IF ErrorID <> WORD#0 THEN Error:=TRUE;END_IF;
			GET_Step	:=INT#0;
		END_IF;		
	
	200: // Error end
			SktClose_Inst(Execute:=TRUE,	Socket:=HTTP_Socket);
		
			IF SktClose_Inst.Done OR SktClose_Inst.Error THEN			
				IF SktClose_Inst.Error THEN ErrorID	:=SktClose_Inst.ErrorID; END_IF;
			Done:=FALSE;
			Busy	:=FALSE;
			Error	:=TRUE;
			IF ErrorID <> WORD#0 THEN Error:=TRUE;END_IF;
			GET_Step	:=INT#0;
		END_IF;
		
END_CASE;	// *************************************THE  END ****************************************
